import './index.css';
import { useState } from 'react';
import { usePortfolio } from './hooks/usePortfolio';
import StockCard from './components/StockCard';
import AlertPanel from './components/AlertPanel';

const TICKER_LABELS = { HLT: 'HEALTH', WLT: 'WEALTH', SOC: 'SOCIAL' };

export default function App() {
  const { portfolio, loading, error, lastUpdated, logActivity, syncGroww } = usePortfolio();
  const [syncMsg, setSyncMsg] = useState(null);

  const handleSync = async () => {
    setSyncMsg('Syncing Groww...');
    const res = await syncGroww();
    if (res?.wlt) {
      setSyncMsg(`WLT synced → ${res.wlt.new_price.toFixed(0)} VTL (${res.wlt.signal})`);
      setTimeout(() => setSyncMsg(null), 4000);
    }
  };

  // ── Loading ──────────────────────────────────────────────────────
  if (loading && !portfolio) return (
    <div style={{
      minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center',
      flexDirection: 'column', gap: 16,
    }}>
      <div style={{
        fontFamily: 'var(--font-display)', fontSize: 28, fontWeight: 800,
        background: 'linear-gradient(135deg, var(--gold), #fff)',
        WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent',
        letterSpacing: '-0.02em',
      }}>
        VitalityX
      </div>
      <div style={{ fontFamily: 'var(--font-mono)', fontSize: 12, color: 'var(--text-dim)', letterSpacing: '0.1em' }}>
        MARKET OPENING...
      </div>
    </div>
  );

  // ── Error ────────────────────────────────────────────────────────
  if (error) return (
    <div style={{
      minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center',
      padding: 24,
    }}>
      <div style={{
        background: 'var(--bg-card)', border: '1px solid var(--red)',
        borderRadius: 'var(--radius-lg)', padding: 32, maxWidth: 400, textAlign: 'center',
      }}>
        <div style={{ fontSize: 32, marginBottom: 16 }}>⚠</div>
        <div style={{ fontFamily: 'var(--font-display)', fontWeight: 700, marginBottom: 8, color: 'var(--red)' }}>
          API Offline
        </div>
        <div style={{ fontSize: 13, color: 'var(--text-secondary)' }}>{error}</div>
        <div style={{ marginTop: 12, fontFamily: 'var(--font-mono)', fontSize: 11, color: 'var(--text-dim)' }}>
          Run: uvicorn main:app --reload
        </div>
      </div>
    </div>
  );

  const totalVTL   = portfolio?.total_vtl || 0;
  const stocks     = portfolio?.stocks || [];
  const alerts     = portfolio?.alerts || [];
  const tickerData = stocks.map(s => ({
    label: TICKER_LABELS[s.ticker] || s.ticker,
    price: s.price.toFixed(0),
    pct: s.change_pct.toFixed(2),
    dir: s.direction,
  }));

  return (
    <div style={{ minHeight: '100vh', maxWidth: 1100, margin: '0 auto', padding: '0 24px 60px' }}>

      {/* ── Ticker strip ─────────────────────────────────────────── */}
      <div style={{
        borderBottom: '1px solid var(--border)',
        overflow: 'hidden',
        height: 36,
        display: 'flex',
        alignItems: 'center',
        position: 'relative',
      }}>
        <div style={{
          display: 'flex', gap: 40, alignItems: 'center',
          animation: 'ticker 18s linear infinite',
          whiteSpace: 'nowrap',
        }}>
          {[...tickerData, ...tickerData].map((t, i) => (
            <span key={i} style={{
              fontFamily: 'var(--font-mono)', fontSize: 11, display: 'flex', gap: 8, alignItems: 'center',
            }}>
              <span style={{ color: 'var(--text-secondary)', letterSpacing: '0.08em' }}>{t.label}</span>
              <span style={{ color: t.dir === 'up' ? 'var(--green)' : t.dir === 'down' ? 'var(--red)' : 'var(--text-dim)' }}>
                {t.price} VTL
              </span>
              <span style={{ color: t.dir === 'up' ? 'var(--green)' : t.dir === 'down' ? 'var(--red)' : 'var(--text-dim)', opacity: 0.7 }}>
                {t.dir === 'up' ? '▲' : t.dir === 'down' ? '▼' : '—'}{Math.abs(t.pct)}%
              </span>
            </span>
          ))}
        </div>
      </div>

      {/* ── Header ───────────────────────────────────────────────── */}
      <div style={{
        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        padding: '32px 0 28px',
        animation: 'fadeUp 0.4s ease forwards',
      }}>
        <div>
          <div style={{
            fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 32,
            background: 'linear-gradient(135deg, var(--gold) 0%, #fff 60%)',
            WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent',
            letterSpacing: '-0.03em', lineHeight: 1,
          }}>
            VitalityX
          </div>
          <div style={{
            fontFamily: 'var(--font-mono)', fontSize: 11, color: 'var(--text-dim)',
            marginTop: 6, letterSpacing: '0.08em',
          }}>
            LIFE PORTFOLIO · {new Date().toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }).toUpperCase()}
          </div>
        </div>

        <div style={{ textAlign: 'right' }}>
          <div style={{
            fontFamily: 'var(--font-mono)', fontSize: 36, fontWeight: 500,
            color: 'var(--gold)', letterSpacing: '-0.02em', lineHeight: 1,
          }}>
            {totalVTL.toLocaleString('en-IN', { maximumFractionDigits: 0 })}
            <span style={{ fontSize: 14, color: 'var(--text-secondary)', marginLeft: 6 }}>VTL</span>
          </div>
          <div style={{ fontFamily: 'var(--font-mono)', fontSize: 11, color: 'var(--text-dim)', marginTop: 4 }}>
            TOTAL PORTFOLIO VALUE
          </div>
        </div>
      </div>

      {/* ── Sync notification ────────────────────────────────────── */}
      {syncMsg && (
        <div style={{
          background: 'var(--gold-dim)', border: '1px solid var(--gold)30',
          borderRadius: 'var(--radius-sm)', padding: '10px 16px', marginBottom: 16,
          fontFamily: 'var(--font-mono)', fontSize: 12, color: 'var(--gold)',
          animation: 'fadeUp 0.2s ease forwards',
        }}>
          ◈ {syncMsg}
        </div>
      )}

      {/* ── Stock cards ──────────────────────────────────────────── */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
        gap: 16,
        marginBottom: 24,
      }}>
        {stocks.map((s, i) => (
          <div key={s.ticker} style={{ animationDelay: `${i * 0.08}s` }}>
            <StockCard
              stock={s}
              onLog={(type) => logActivity(type)}
              onSync={handleSync}
            />
          </div>
        ))}
      </div>

      {/* ── Alerts ───────────────────────────────────────────────── */}
      <AlertPanel alerts={alerts}/>

      {/* ── Footer ───────────────────────────────────────────────── */}
      <div style={{
        marginTop: 32, paddingTop: 20,
        borderTop: '1px solid var(--border)',
        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
      }}>
        <div style={{ fontFamily: 'var(--font-mono)', fontSize: 10, color: 'var(--text-dim)', letterSpacing: '0.06em' }}>
          VITALITYX EXCHANGE · CURRENCY: VITALS (VTL)
        </div>
        <div style={{ fontFamily: 'var(--font-mono)', fontSize: 10, color: 'var(--text-dim)' }}>
          {lastUpdated ? `LAST UPDATED ${lastUpdated.toLocaleTimeString('en-IN')}` : 'LIVE'}
        </div>
      </div>

    </div>
  );
}
